 * @returns The newly created record with generated id and typeName
 * @public
 */
create(
	properties: Expand<Pick<R, RequiredProperties> & Omit<Partial<R>, RequiredProperties>>
): R {
	const result = {
		...this.createDefaultProperties(),
		id: (properties as Partial<R>).id ?? this.createId(),
	} as any

	for (const [k, v] of objectMapEntries(properties)) {
		if (v !== undefined) {
			result[k] = v
		}
	}
